def transform(grid):
 g=[r[:] for r in grid]; p={}
 for r,row in enumerate(grid):
  for c,v in enumerate(row):
   if v:p.setdefault(v,[]).append((r,c))
 for v,qs in p.items():
  for r,c in qs:
   for R,C in qs:
    dr=R-r;dc=C-c
    if dr==0 or dc==0 or abs(dr)==abs(dc):
     n=max(abs(dr),abs(dc)); sr=(R>r)-(R<r);sc=(C>c)-(C<c)
     for k in range(1,n):g[r+sr*k][c+sc*k]=v
 return g

def transform(grid):
 out=[x[:] for x in grid];h=len(grid);w=len(grid[0])
 for v in range(1,10):
  q=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==v]
  for r,c in q:
   for R,C in q:
    dr=R-r;dc=C-c
    if dr==0 or dc==0 or abs(dr)==abs(dc):
     n=max(abs(dr),abs(dc));a=0 if dr==0 else (1 if dr>0 else -1);b=0 if dc==0 else (1 if dc>0 else -1)
     for k in range(n+1):out[r+a*k][c+b*k]=v
 return out
